CREATE OR REPLACE PROCEDURE dbp_macro.m_insert_nachlieferungprocess(IN MANDANT_ID FLOAT64, IN GP_EXP_NAME STRING, IN DAT_START STRING, IN ANZAHL_DATEIEN FLOAT64, IN LDAP_USER STRING, IN WUP_ID FLOAT64, IN ART_ID FLOAT64, IN REQUEST_ID FLOAT64)
BEGIN
DECLARE sql_stmt STRING;
DECLARE sql_commit STRING;
BEGIN TRANSACTION;
SET sql_stmt  =  '''INSERT INTO dbp_msi_data.ts_nachlieferung_1 (nachlieferung_request_id, gp_exp_name, mandant_id, wup_id,  dat_start, art_id, anzahl_dateien, active_fg, ldap_user, datzeit_insert, td_update, td_insert) (SELECT CAST(@REQUEST_ID AS INTEGER) AS nachlieferung_request_id,   @GP_EXP_NAME AS gp_exp_name,   CAST(@MANDANT_ID AS INTEGER) AS mandant_id,   CAST(@WUP_ID AS INTEGER) AS wup_id,   CAST(@DAT_START AS DATE) AS dat_start,   CAST(@ART_ID AS INTEGER) AS art_id,   CAST(@ANZAHL_DATEIEN AS INTEGER) AS anzahl_dateien,   1 AS active_fg,   @LDAP_USER AS ldap_user,   CAST(CURRENT_TIMESTAMP() AS DATETIME) AS datzeit_insert,   CURRENT_TIMESTAMP() AS td_update,   CURRENT_TIMESTAMP() AS td_insert) ''';

EXECUTE IMMEDIATE (sql_stmt) USING IF(REQUEST_ID = CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64), REQUEST_ID) AS REQUEST_ID,  IF(GP_EXP_NAME = CAST(NULL AS STRING), CAST(NULL AS STRING), GP_EXP_NAME) AS GP_EXP_NAME,  IF(MANDANT_ID = CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64), MANDANT_ID) AS MANDANT_ID,  IF(WUP_ID = CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64), WUP_ID) AS WUP_ID,  IF(ART_ID = CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64), ART_ID) AS ART_ID,  IF(DAT_START = CAST(NULL AS STRING), CAST(NULL AS STRING), DAT_START) AS DAT_START,  IF(ANZAHL_DATEIEN = CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64), ANZAHL_DATEIEN) AS ANZAHL_DATEIEN,  IF(LDAP_USER = CAST(NULL AS STRING), CAST(NULL AS STRING), LDAP_USER) AS LDAP_USER;

SET sql_commit  =  'COMMIT TRANSACTION';

EXECUTE IMMEDIATE (sql_commit);
END;

